import React from 'react';

const ScoreCard = ({ title, score, color = 'gold' }) => {
  const colorStyles = {
    gold: {
      border: 'border-gold-300/30',
      text: 'text-gold-300',
      glow: 'shadow-gold-glow',
      stroke: '#FDE047'
    },
    bronze: {
      border: 'border-bronze-100/30',
      text: 'text-bronze-100',
      glow: 'shadow-amber-glow',
      stroke: '#AF8F6F'
    },
    copper: {
      border: 'border-bronze-400/30',
      text: 'text-bronze-200',
      glow: 'shadow-gold-glow',
      stroke: '#C7A785'
    }
  };

  const currentStyle = colorStyles[color] || colorStyles.gold;
  const roundedScore = Math.round(score || 0);

  return (
    <div className={`glass-card p-5 rounded-2xl border ${currentStyle.border} transition-all duration-300 hover:scale-[1.03] flex items-center justify-between`}>
      <div>
        <p className="text-xs font-mono tracking-wider text-bronze-200 uppercase mb-1">{title}</p>
        <p className={`text-3xl font-heading font-extrabold ${currentStyle.text}`}>
          {roundedScore}<span className="text-lg text-bronze-200 font-normal">%</span>
        </p>
      </div>

      {/* Mini Circular Golden Meter */}
      <div className={`relative w-14 h-14 rounded-full flex items-center justify-center bg-bronze-950/80 ${currentStyle.glow}`}>
        <svg className="w-full h-full transform -rotate-90">
          <circle
            cx="28"
            cy="28"
            r="22"
            stroke="rgba(248, 244, 225, 0.1)"
            strokeWidth="4"
            fill="none"
          />
          <circle
            cx="28"
            cy="28"
            r="22"
            stroke={currentStyle.stroke}
            strokeWidth="4"
            fill="none"
            strokeDasharray={`${2 * Math.PI * 22}`}
            strokeDashoffset={`${2 * Math.PI * 22 * (1 - roundedScore / 100)}`}
            strokeLinecap="round"
          />
        </svg>
      </div>
    </div>
  );
};

export default ScoreCard;
